<?php
session_start();require_once '../conexion.php';if(!isset($_SESSION['usuario_id'])||$_SESSION['rol']!=='admin'){header('Location: ../login.php');exit;}$id=trim($_GET['id']??'');$stmt=$conexion->prepare("SELECT p.CI AS id,p.usuario AS nombre,p.usuario,o.Estado AS estado,o.hora_ingreso FROM Persona p JOIN Operario o ON o.CI=p.CI WHERE p.CI=? AND p.Rol='Operario'");$stmt->bind_param('s',$id);$stmt->execute();$operario=$stmt->get_result()->fetch_assoc();if(!$operario){header('Location: operarios.php?error='.urlencode('Operario no encontrado.'));exit;}$stmt=$conexion->prepare("SELECT COUNT(*) total FROM Pedido WHERE ci_operario=? AND estado='Completado'");$stmt->bind_param('s',$id);$stmt->execute();$pedidos=(int)$stmt->get_result()->fetch_assoc()['total'];$stmt=$conexion->prepare("SELECT DATE(fecha_hora) fecha, MIN(TIME(fecha_hora)) hora_inicio, MAX(TIME(fecha_hora)) hora_fin, TIMEDIFF(MAX(TIME(fecha_hora)),MIN(TIME(fecha_hora))) tiempo FROM Registra WHERE ci_operario=? GROUP BY DATE(fecha_hora) ORDER BY fecha DESC LIMIT 20");$stmt->bind_param('s',$id);$stmt->execute();$historial=$stmt->get_result();$filas=[];$totalSeg=0;while($fila=$historial->fetch_assoc()){$filas[]=$fila;if($fila['tiempo']){$a=explode(':',$fila['tiempo']);$totalSeg+=(int)$a[0]*3600+(int)$a[1]*60+(int)$a[2];}}$horas=floor($totalSeg/3600);$minutos=floor(($totalSeg%3600)/60);$tiempo=$horas.'h '.str_pad($minutos,2,'0',STR_PAD_LEFT).'m';$promedioTexto=($pedidos>0?round(($totalSeg/$pedidos)/60):0).'m';
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Perfil del operario | Softyle</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="../CSS/sistema.css"></head><body class="sistema-body"><nav class="sistema-navbar"><div class="navbar-brand-sistema"><div class="navbar-logo"><i class="bi bi-box-seam"></i></div><div><strong>SOFTYLE</strong><small>Panel administrativo</small></div></div><a href="operarios.php" class="btn-logout"><i class="bi bi-arrow-left"></i></a></nav><main class="admin-container"><a href="operarios.php" class="volver-link"><i class="bi bi-arrow-left"></i> Volver a operarios</a><section class="perfil-operario"><div class="perfil-icon"><i class="bi bi-person"></i></div><div class="perfil-info"><span class="dashboard-label">PERFIL DEL OPERARIO</span><h1><?php echo htmlspecialchars($operario['nombre'],ENT_QUOTES,'UTF-8');?></h1><p>Usuario: <strong><?php echo htmlspecialchars($operario['usuario'],ENT_QUOTES,'UTF-8');?></strong></p><?php if(strtolower($operario['estado'])==='activo'){?><span class="estado activo">Activo</span><?php }else{?><span class="estado">Inactivo</span><?php }?></div></section><section class="perfil-stats"><div class="perfil-stat"><i class="bi bi-clipboard-check"></i><span>Pedidos completados</span><strong><?php echo $pedidos;?></strong></div><div class="perfil-stat"><i class="bi bi-clock"></i><span>Tiempo trabajado</span><strong><?php echo htmlspecialchars($tiempo,ENT_QUOTES,'UTF-8');?></strong></div><div class="perfil-stat"><i class="bi bi-stopwatch"></i><span>Promedio por pedido</span><strong><?php echo htmlspecialchars($promedioTexto,ENT_QUOTES,'UTF-8');?></strong></div></section><section class="admin-table-card"><div class="section-title"><h2>Historial de trabajo</h2><p>Registro de jornadas del operario.</p></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Inicio</th><th>Fin</th><th>Tiempo</th></tr></thead><tbody><?php if(count($filas)===0){?><tr><td colspan="4" class="text-center">No hay jornadas registradas.</td></tr><?php } ?><?php foreach($filas as $fila){?><tr><td><?php echo htmlspecialchars($fila['fecha'],ENT_QUOTES,'UTF-8');?></td><td><?php echo htmlspecialchars($fila['hora_inicio'],ENT_QUOTES,'UTF-8');?></td><td><?php echo $fila['hora_fin']!==null?htmlspecialchars($fila['hora_fin'],ENT_QUOTES,'UTF-8'):'En curso';?></td><td><?php echo $fila['tiempo']!==null?htmlspecialchars($fila['tiempo'],ENT_QUOTES,'UTF-8'):'-';?></td></tr><?php }?></tbody></table></div></section></main></body></html>
